struct GitHubIcon: View {
    let kind: GitHubIconKind
    var size: CGFloat = 16
    var body: some View {
        GitHubIconShape(paths: kind.paths).stroke(style: StrokeStyle(lineWidth: size / 16, lineCap: .round, lineJoin: .round)).frame(width: size, height: size).accessibilityHidden(true)
    }
}

private struct GitHubIconShape: Shape {
    let paths: [String]
    nonisolated func path(in rect: CGRect) -> Path { GitHubVectorPath.combinedPath(paths, in: rect) }
}

public enum GitHubNativeIcon {
    public static func svg(for item: GitHubValue) -> String { svg(item.statusIcon) }
    public static var mergeSVG: String { svg(.merged) }
    private static func svg(_ kind: GitHubIconKind) -> String {
        let paths = kind.paths.map { "<path d=\"\($0)\"/>" }.joined()
        return "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\(paths)</g></svg>"
    }
}
